import structimport sysimport osimport tkinter as tkfrom tkinter import filedialogroot = tk.Tk()root.withdraw()filepath = filedialog.askopenfilename()# Just give the filepath below and the code will try to fix the source file.# filepath=r'C:\Users\michael.cheng\Documents\Zemax\Objects\Sources\Source Files\SFT-10-CG_100000Rays_ZEMAX.dat'bfile=open(filepath, 'rb')filesize = os.fstat(bfile.fileno()).st_size#filesize = bfile.seek(0,2)#bfile.seek(0,0)Identifier = int.from_bytes(bfile.read(4), byteorder='little')NbrRays = int.from_bytes(bfile.read(4), byteorder='little')Description = bfile.read(100).decode()SourceFlux = struct.unpack('f', bfile.read(4))[0]RaySetFlux = struct.unpack('f', bfile.read(4))[0]Wavelength = struct.unpack('f', bfile.read(4))[0]InclinationBeg = struct.unpack('f', bfile.read(4))[0]InclinationEnd = struct.unpack('f', bfile.read(4))[0]AzimuthBeg = struct.unpack('f', bfile.read(4))[0]AzimuthEnd = struct.unpack('f', bfile.read(4))[0]DimensionUnits = int.from_bytes(bfile.read(4), byteorder='little')LocX = struct.unpack('f', bfile.read(4))[0]LocY = struct.unpack('f', bfile.read(4))[0]LocZ = struct.unpack('f', bfile.read(4))[0]RotX = struct.unpack('f', bfile.read(4))[0]RotY = struct.unpack('f', bfile.read(4))[0]RotZ = struct.unpack('f', bfile.read(4))[0]ScaleX = struct.unpack('f', bfile.read(4))[0]ScaleY = struct.unpack('f', bfile.read(4))[0]ScaleZ = struct.unpack('f', bfile.read(4))[0]bfile.read(4*4)ray_format_type = int.from_bytes(bfile.read(4), byteorder='little')flux_type = int.from_bytes(bfile.read(4), byteorder='little')bfile.read(4*2)print('=======================')print('File size =        ' + str(filesize) + ' bytes')print('=======================')print('Identifier =       ' + str(Identifier))print('NbrRays =          ' + str(NbrRays))print('Description =      ' + str(Description))print('SourceFlux =       ' + str(SourceFlux) + ' (The total flux in watts of this source)')print('RaySetFlux =       ' + str(RaySetFlux) + ' (The flux in watts represented by this Ray Set)')print('Wavelength =       ' + str(Wavelength) + ' (The wavelength in microns, 0 if a composite)')print('DimensionUnits =   ' + str(DimensionUnits) + ' (METERS=0, IN=1, CM=2, FEET=3, MM=4)')print('ray_format_type =  ' + str(ray_format_type) + ' (0->flux only, 2->spectral color)')print('flux_type =        ' + str(flux_type) + ' (0->watts, 2->lumens, only if ray_format_type = 0.)')print('=======================')probRay = []if ray_format_type == 0:    for m in range(1,NbrRays+1,1):        bfile.read(4*6)        rest_size = filesize - bfile.tell()        if rest_size >= 4:            flux = struct.unpack('f', bfile.read(4))[0]        else:            print('Error: Loading ' + str(m) + ' th ray failed')            print('There no data for this ray.')            print('bfile.tell() = ' + str(bfile.tell()))            print('rest_size = ' + str(rest_size))            quit()        if flux == 0:            print('The ' + str(m) + ' th ray has 0 flux!')            probRay.append(m)elif ray_format_type == 2:    for m in range(1,NbrRays+1,1):        bfile.read(4*6)        rest_size = filesize - bfile.tell()        if rest_size >= 4:            flux = struct.unpack('f', bfile.read(4))[0]        else:            print('Error: Loading ' + str(m) + ' th ray failed')            print('There no data for this ray.')            print('bfile.tell() = ' + str(bfile.tell()))            print('rest_size = ' + str(rest_size))            quit()        if flux == 0:            print('The ' + str(m) + ' th ray has 0 flux!')            probRay.append(m)        bfile.read(4)else:        print('ray_format_type is in wrong format')if len(probRay) == 0:    print('\nThere is no 0-flux ray found! This source file look good!')    sys.exit()print('There are totally ' + str(len(probRay)) + ' rays with 0-flux found!')print('Starting fix...\n')outfilepath=filepath[0:-4] + '_fixed' + filepath[-4:]outfile=open(outfilepath, 'wb')bfile.seek(0)outfile.write(bfile.read(4))outfile.write(struct.pack("<I",NbrRays - len(probRay)))bfile.read(4)outfile.write(bfile.read(50*4))count = 0if ray_format_type == 0:    for m in range(1,NbrRays+1,1):        if count < len(probRay) and m == probRay[count]:            bfile.read(4*7)            print('Deleting ' + str(m) + 'th ray from the source file. Count: ' + str(count+1))            count = count + 1        else:            outfile.write(bfile.read(4*7))elif ray_format_type == 2:    for m in range(1,NbrRays+1,1):        if count < len(probRay) and m == probRay[count]:            bfile.read(4*8)            print('Deleting ' + str(m) + 'th ray from the source file. Count: ' + str(count+1))            count = count + 1        else:            outfile.write(bfile.read(4*8))else:        print('ray_format_type is in wrong format')print('The checking is finished!')print('Fixed file is saved at: ' + outfilepath)bfile.close()outfile.close()